import java.util.*; import java.io.*; import java.math.BigInteger; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int t = Integer.parseInt(br.readLine()); while (t-- > 0) { StringTokenizer st = new StringTokenizer(br.readLine()); int n = Integer.parseInt(st.nextToken()); int k = Integer.parseInt(st.nextToken()); int[] a = new int[n]; st = new StringTokenizer(br.readLine()); for (int i = 0; i < n; i++) a[i] = Integer.parseInt(st.nextToken()); Arrays.sort(a); int valK = a[k - 1]; int countK = 0; int totalCount = 0; for (int i = 0; i < k; i++) { if (a[i] == valK) countK++; } for (int i = 0; i < n; i++) { if (a[i] == valK) totalCount++; } System.out.println(nCr(totalCount, countK)); } } public static BigInteger nCr(int n, int r) { if (r < 0 || r > n) return BigInteger.ZERO; if (r == 0 || r == n) return BigInteger.ONE; if (r > n / 2) r = n - r; BigInteger res = BigInteger.ONE; for (int i = 1; i <= r; i++) { res = res.multiply(BigInteger.valueOf(n - i + 1)).divide(BigInteger.valueOf(i)); } return res; } }